def compute(vars):
    old_value = vars["v1"]
    new_value = vars["v2"]

    if old_value == 0:
        return None

    change = new_value - old_value
    change_ratio = change / old_value
    percent_change = change_ratio * 100

    return {
        "value": percent_change,
        "trace": {
            "old_value": old_value,
            "new_value": new_value,
            "change": change,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "percentage"
            }
        }
    }
